WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_new_burst_tier, DATE_TRUNC('WEEK', event_time) AS week_start, APPROX_PERCENTILE(island_id, 0.9) AS island_id_p90, SUM(is_new_burst) AS total_is_new_burst, BIT_OR(duration_sec) AS duration_sec_bit_or, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list, COUNT(*) AS cnt, RANK() OVER (PARTITION BY CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END ORDER BY (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 DESC) AS span_minutes_rank FROM sessionized GROUP BY CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', event_time);
